package clauderuntime_test

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/KogenAI/kogen-executor/executor/claudecode"
	"github.com/KogenAI/kogen-executor/testkit/clauderuntime"
)

func install(t *testing.T, o clauderuntime.Options) *clauderuntime.Fixture {
	t.Helper()
	root := t.TempDir()
	o.Home, o.State = filepath.Join(root, "home"), filepath.Join(root, "state")
	return clauderuntime.Install(t, o)
}

func requireSupported(t *testing.T) {
	t.Helper()
	if _, ok := claudecode.Supported(); !ok {
		t.Skip("unsupported platform")
	}
}

func TestVersionAndAuthStatusThroughTheProductionPath(t *testing.T) {
	requireSupported(t)
	fx := install(t, clauderuntime.Options{})
	out, err := claudecode.Probe(context.Background(), fx.Home, "--version")
	if err != nil {
		t.Fatalf("--version: %v", err)
	}
	if got := strings.TrimSpace(string(out)); got != clauderuntime.VersionOutput() || !claudecode.Pinned(got) {
		t.Fatalf("--version answered %q, want the pinned %q", got, clauderuntime.VersionOutput())
	}
	out, err = claudecode.Probe(context.Background(), fx.Home, "auth", "status", "--json")
	if err != nil {
		t.Fatalf("auth status: %v", err)
	}
	if got := strings.TrimSpace(string(out)); got != clauderuntime.AuthStatusJSON {
		t.Fatalf("auth status answered %q, want %q", got, clauderuntime.AuthStatusJSON)
	}
}

func TestRoundFilesAndPromptsStayUnderTheCallersState(t *testing.T) {
	requireSupported(t)
	fx := install(t, clauderuntime.Options{Rounds: [][]string{{clauderuntime.ResultLine(nil)}, {clauderuntime.ResultLine(nil)}}})
	for _, name := range []string{"round-1.jsonl", "round-2.jsonl"} {
		if _, err := os.Stat(filepath.Join(fx.State, name)); err != nil {
			t.Fatalf("round file %s: %v", name, err)
		}
	}
	if _, err := os.Stat(claudecode.RuntimePath(fx.Home)); err != nil {
		t.Fatalf("runtime at claudecode.RuntimePath: %v", err)
	}
}

func TestResultLineCarriesTheSessionToken(t *testing.T) {
	line := clauderuntime.ResultLine(map[string]any{"result": "x"})
	for _, want := range []string{`"type":"result"`, `"session_id":"` + clauderuntime.SessionID + `"`, `"result":"x"`} {
		if !strings.Contains(line, want) {
			t.Fatalf("result line %s lacks %s", line, want)
		}
	}
}

